class Solution {
    public int minimumTime(List<Integer> nums1,List<Integer> nums2,int x){
        int n=nums1.size();
        int[][] pairs=new int[n][2];
        long base=0,growth=0;
        for(int i=0;i<n;i++){
            pairs[i][0]=nums1.get(i);
            pairs[i][1]=nums2.get(i);
            base+=pairs[i][0];
            growth+=pairs[i][1];
        }
        Arrays.sort(pairs,(a,b)->Integer.compare(a[1],b[1]));
        long[] dp=new long[n+1];
        for(int i=0;i<n;i++)for(int selected=i+1;selected>=1;selected--)dp[selected]=Math.max(dp[selected],dp[selected-1]+pairs[i][0]+(long)pairs[i][1]*selected);
        for(int seconds=0;seconds<=n;seconds++)if(base+growth*seconds-dp[seconds]<=x)return seconds;
        return -1;
    }
}

code.kotlin:
class Solution {
    fun minimumTime(nums1:List<Int>,nums2:List<Int>,x:Int):Int{
        val n=nums1.size;
        val pairs=Array(n){
            i->intArrayOf(nums1[i],nums2[i])
        };
        pairs.sortWith(Comparator{
            a,b->a[1].compareTo(b[1])
        });
        var base=0L;
        var growth=0L;
        for(pair in pairs){
            base+=pair[0];
            growth+=pair[1]
        };
        val dp=LongArray(n+1);
        for(i in pairs.indices)for(selected in i+1 downTo 1)dp[selected]=maxOf(dp[selected],dp[selected-1]+pairs[i][0]+pairs[i][1].toLong()*selected);
        for(seconds in 0..n)if(base+growth*seconds-dp[seconds]<=x)return seconds;
        return -1
    }
}

